//! Check it with:  fast-anything verify TPTBox.core.np_utils.unique_integers
//!
//! The Python version returns the same sorted list on every path (bincount for unsigned arrays with a
//! maximum below 2**20, np.unique otherwise); only an empty unsigned array differs: `arr.max()` raises.
//! Here 8- and 16-bit arrays are marked in a fixed table in one pass, wider ones go through a min/max
//! pass and then a table over the value range (range below 2**20) or a sort.

use numpy::{PyArrayDyn, PyArrayMethods, PyUntypedArray};
use pyo3::exceptions::{PyTypeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::PyList;

/// Ranges below this are counted in a table (the bincount threshold of the Python version).
const TABLE_LIMIT: u64 = 1 << 20;

trait Int: Copy + Ord + numpy::Element {
    const SIGNED: bool;
    /// Order-preserving map to u64 (signed values get their sign bit flipped).
    fn key(self) -> u64;
    fn wide(self) -> i128;
}

macro_rules! int {
    ($($t:ty => $s:expr, $flip:expr);*) => {$(
        impl Int for $t {
            const SIGNED: bool = $s;
            #[inline(always)]
            fn key(self) -> u64 {
                (self as i64 as u64) ^ $flip
            }
            #[inline(always)]
            fn wide(self) -> i128 {
                self as i128
            }
        }
    )*};
}
// unsigned: `as i64 as u64` is the value itself (u64 reinterprets, smaller types zero-extend)
int!(u8 => false, 0; u16 => false, 0; u32 => false, 0; u64 => false, 0;
     i8 => true, 1 << 63; i16 => true, 1 << 63; i32 => true, 1 << 63; i64 => true, 1 << 63);

/// Values present in `values`, ascending, given that every key lies in `lo..lo + size`.
fn table<T: Int>(values: impl Iterator<Item = T>, lo: u64, size: usize) -> Vec<i128> {
    let mut seen = vec![false; size];
    for v in values {
        seen[(v.key() - lo) as usize] = true;
    }
    let flip = if T::SIGNED { 1u64 << 63 } else { 0 };
    let value = |k: u64| if T::SIGNED { ((k ^ flip) as i64) as i128 } else { k as i128 };
    seen.iter().enumerate().filter(|(_, s)| **s).map(|(i, _)| value(lo + i as u64)).collect()
}

fn unique_of<T: Int, I: Iterator<Item = T> + Clone>(values: I, len: usize) -> PyResult<Option<Vec<i128>>> {
    if len == 0 {
        // np.bincount path: arr.max() raises; np.unique path: []
        return if T::SIGNED {
            Ok(Some(Vec::new()))
        } else {
            Err(PyValueError::new_err("zero-size array to reduction operation maximum which has no identity"))
        };
    }
    let bits = std::mem::size_of::<T>() * 8;
    if bits <= 16 {
        let lo = if T::SIGNED { (1u64 << 63) - (1u64 << (bits - 1)) } else { 0 };
        return Ok(Some(table(values, lo, 1 << bits)));
    }
    let (lo, hi) = values.clone().map(Int::key).fold((u64::MAX, 0u64), |(lo, hi), k| (lo.min(k), hi.max(k)));
    if hi - lo < TABLE_LIMIT {
        return Ok(Some(table(values, lo, (hi - lo) as usize + 1)));
    }
    let mut all: Vec<T> = values.collect();
    all.sort_unstable();
    all.dedup();
    Ok(Some(all.into_iter().map(Int::wide).collect()))
}

/// The distinct values of `arr` if it is a native-byte-order array of `T`, None if it is not.
fn try_type<T: Int>(arr: &Bound<'_, PyAny>) -> PyResult<Option<Vec<i128>>> {
    let Ok(a) = arr.cast::<PyArrayDyn<T>>() else {
        return Ok(None);
    };
    let ro = a.readonly();
    match ro.as_slice() {
        Ok(s) => unique_of(s.iter().copied(), s.len()),
        Err(_) => {
            let view = ro.as_array();
            unique_of(view.iter().copied(), view.len())
        }
    }
}

fn dispatch(arr: &Bound<'_, PyAny>) -> PyResult<Option<Vec<i128>>> {
    macro_rules! each {
        ($($t:ty),*) => {$(
            if let Some(v) = try_type::<$t>(arr)? {
                return Ok(Some(v));
            }
        )*};
    }
    each!(u8, u16, u32, u64, i8, i16, i32, i64);
    Ok(None)
}

#[pyfunction]
fn unique_integers<'py>(py: Python<'py>, arr: &Bound<'py, PyAny>) -> PyResult<Bound<'py, PyList>> {
    let dtype = arr.getattr("dtype")?;
    let kind: String = dtype.getattr("kind")?.extract()?;
    if kind != "i" && kind != "u" {
        return Err(PyTypeError::new_err(format!("expected an integer array, got {}", dtype.str()?)));
    }
    let values = match dispatch(arr)? {
        Some(v) => v,
        None => {
            // a numpy scalar, a byte-swapped array or a platform alias numpy-rs does not map: native ndarray copy
            let np = py.import("numpy")?;
            let native_dtype = dtype.call_method1("newbyteorder", ("=",))?;
            let base = if arr.cast::<PyUntypedArray>().is_ok() { arr.clone() } else { np.call_method1("asarray", (arr,))? };
            let native = base.call_method1("astype", (native_dtype,))?;
            dispatch(&native)?.ok_or_else(|| PyTypeError::new_err(format!("unsupported integer dtype {}", dtype.str().unwrap())))?
        }
    };
    // Python ints: i64 covers every signed value; a value above i64::MAX comes from a uint64 array,
    // whose values are all non-negative and fit u64
    if values.last().is_some_and(|&v| v > i64::MAX as i128) {
        PyList::new(py, values.into_iter().map(|v| v as u64))
    } else {
        PyList::new(py, values.into_iter().map(|v| v as i64))
    }
}

